package com.example.banking.exception;
import com.example.banking.dto.ApiDtos.ErrorResponse; import jakarta.servlet.http.HttpServletRequest; import java.time.Instant; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.http.*; import org.springframework.web.HttpRequestMethodNotSupportedException; import org.springframework.web.HttpMediaTypeNotSupportedException; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.MissingRequestHeaderException; import org.springframework.web.bind.MissingServletRequestParameterException; import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException; import org.springframework.http.converter.HttpMessageNotReadableException; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice
public class ApiExceptionHandler {
 private static final Logger LOG=LoggerFactory.getLogger(ApiExceptionHandler.class);
 @ExceptionHandler(ApiException.class) ResponseEntity<ErrorResponse> api(ApiException e,HttpServletRequest r){return ResponseEntity.status(e.getStatus()).body(new ErrorResponse(Instant.now(),e.getStatus().value(),e.getStatus().getReasonPhrase(),e.getMessage(),r.getRequestURI()));}
 @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ErrorResponse> validation(MethodArgumentNotValidException e,HttpServletRequest r){String msg=e.getBindingResult().getFieldErrors().stream().findFirst().map(x->x.getField()+" "+x.getDefaultMessage()).orElse("Invalid request");return ResponseEntity.badRequest().body(new ErrorResponse(Instant.now(),400,"Bad Request",msg,r.getRequestURI()));}
 @ExceptionHandler({HttpMessageNotReadableException.class,MissingRequestHeaderException.class}) ResponseEntity<ErrorResponse> malformed(Exception e,HttpServletRequest r){return ResponseEntity.badRequest().body(new ErrorResponse(Instant.now(),400,"Bad Request","Request body or required header is invalid",r.getRequestURI()));}
 @ExceptionHandler({MissingServletRequestParameterException.class,MethodArgumentTypeMismatchException.class}) ResponseEntity<ErrorResponse> parameter(Exception e,HttpServletRequest r){return ResponseEntity.badRequest().body(new ErrorResponse(Instant.now(),400,"Bad Request","A request parameter is missing or invalid",r.getRequestURI()));}
 @ExceptionHandler(DataIntegrityViolationException.class) ResponseEntity<ErrorResponse> conflict(DataIntegrityViolationException e,HttpServletRequest r){return ResponseEntity.status(409).body(new ErrorResponse(Instant.now(),409,"Conflict","The request conflicts with existing data",r.getRequestURI()));}
 @ExceptionHandler(HttpRequestMethodNotSupportedException.class) ResponseEntity<ErrorResponse> method(HttpRequestMethodNotSupportedException e,HttpServletRequest r){return ResponseEntity.status(405).body(new ErrorResponse(Instant.now(),405,"Method Not Allowed","The HTTP method is not supported for this route",r.getRequestURI()));}
 @ExceptionHandler(HttpMediaTypeNotSupportedException.class) ResponseEntity<ErrorResponse> mediaType(HttpMediaTypeNotSupportedException e,HttpServletRequest r){return ResponseEntity.status(415).body(new ErrorResponse(Instant.now(),415,"Unsupported Media Type","The request content type is not supported",r.getRequestURI()));}
 @ExceptionHandler(Exception.class) ResponseEntity<ErrorResponse> unexpected(Exception e,HttpServletRequest r){LOG.error("Unhandled request failure type={} path={}",e.getClass().getSimpleName(),r.getRequestURI());return ResponseEntity.status(500).body(new ErrorResponse(Instant.now(),500,"Internal Server Error","The request could not be completed",r.getRequestURI()));}
}
